package proto

import (
	"crypto/rand"
	"crypto/sha256"
	"fmt"
	"io"

	"golang.org/x/crypto/chacha20poly1305"
	"golang.org/x/crypto/curve25519"
	"golang.org/x/crypto/hkdf"
)

// PSK delivery to the hub.
//
// The network PSK is generated by the creator's client and meshd must never
// see it in plaintext — but the relay hub needs it to complete WireGuard
// handshakes with members. The creator therefore encrypts the PSK to the
// hub's X25519 public key with an ephemeral key pair:
//
//	sealed = ephemeralPub(32) || nonce(12) || ChaCha20Poly1305(
//	    key = HKDF-SHA256( X25519(ephemeralPriv, hubPub), salt=nil,
//	                       info="yousj-mesh-psk" ),
//	    nonce, plaintext = psk)
//
// meshd only stores and forwards the sealed blob (returned solely on the
// hub-token-authenticated /v1/hub/peers endpoint). The same construction is
// implemented by the Android client (cryptography package primitives).
const pskHKDFInfo = "yousj-mesh-psk"

func pskKey(shared []byte) ([]byte, error) {
	r := hkdf.New(sha256.New, shared, nil, []byte(pskHKDFInfo))
	key := make([]byte, 32)
	if _, err := io.ReadFull(r, key); err != nil {
		return nil, err
	}
	return key, nil
}

// SealPSKForHub encrypts psk (32 bytes) to the hub's X25519 public key.
func SealPSKForHub(psk, hubPub []byte) (string, error) {
	ephPriv := make([]byte, 32)
	if _, err := rand.Read(ephPriv); err != nil {
		return "", err
	}
	ephPub, err := curve25519.X25519(ephPriv, curve25519.Basepoint)
	if err != nil {
		return "", err
	}
	shared, err := curve25519.X25519(ephPriv, hubPub)
	if err != nil {
		return "", err
	}
	key, err := pskKey(shared)
	if err != nil {
		return "", err
	}
	aead, err := chacha20poly1305.New(key)
	if err != nil {
		return "", err
	}
	nonce := make([]byte, aead.NonceSize())
	if _, err := rand.Read(nonce); err != nil {
		return "", err
	}
	out := append(append(ephPub, nonce...), aead.Seal(nil, nonce, psk, nil)...)
	return B64.EncodeToString(out), nil
}

// OpenPSKFromHub decrypts a sealed PSK with the hub's X25519 private key.
func OpenPSKFromHub(sealedB64 string, hubPriv []byte) ([]byte, error) {
	raw, err := B64.DecodeString(sealedB64)
	if err != nil {
		return nil, err
	}
	if len(raw) < 32+12+16 {
		return nil, fmt.Errorf("sealed psk too short")
	}
	ephPub, nonce, ct := raw[:32], raw[32:44], raw[44:]
	shared, err := curve25519.X25519(hubPriv, ephPub)
	if err != nil {
		return nil, err
	}
	key, err := pskKey(shared)
	if err != nil {
		return nil, err
	}
	aead, err := chacha20poly1305.New(key)
	if err != nil {
		return nil, err
	}
	return aead.Open(nil, nonce, ct, nil)
}
